sys_ux_client_script.script:
function evaluateProperty({ api, helpers }) {
    const kpi = api.data.sam_kpi_foundation_1.output.businessunit_kpi;
    console.log("kalai company",JSON.stringify(kpi, null, 4));
    // Initialize the HTML table string
    let tableHtml = `
        <table style="width: 100%; border-collapse: collapse; margin-top: 20px; font-family: 'Arial', sans-serif; background-color: #f9f9f9;">
            <thead>
                <tr style="background-color: #2e86c1; color: white; text-align: left; font-size: 16px;">
                    <th style="padding: 12px; border: 1px solid #ddd;">KPI</th>
                    <th style="padding: 12px; border: 1px solid #ddd;">Count</th>
                    <th style="padding: 12px; border: 1px solid #ddd;">Impact</th>
                    <th style="padding: 12px; border: 1px solid #ddd;">Recommendation</th>
                </tr>
            </thead>
            <tbody>
    `;

    // Loop through the kpi array and generate table rows
    kpi.forEach(kpis => {
        // Placeholder data for the new columns (KPI, Count, Impact, Recommendation)
        let kpi = kpis.kpi || "Unknown KPI"; // Assuming the KPI is the kpis ID
        let count = kpis.field ? kpis.field_value : 0; // Count is 1 if active, 0 if inactive
        let impact = kpis.active ? 'High' : 'Low'; // Impact is High if active, Low if inactive
        let recommendation = kpis.active ? 'No Action Needed' : 'Activate the kpis'; // Recommendation based on active state

        tableHtml += `
            <tr style="border-bottom: 1px solid #ddd; transition: background-color 0.3s;">
                <td style="padding: 10px; text-align: center; border-right: 1px solid #ddd; font-weight: bold;">${kpi}</td>
                <td style="padding: 10px; text-align: center; border-right: 1px solid #ddd;">${count}</td>
                <td style="padding: 10px; text-align: center; border-right: 1px solid #ddd;">${impact}</td>
                <td style="padding: 10px; text-align: center; font-weight: bold;">
                    ${recommendation}
                </td>
            </tr>
        `;
    });

    // Close the table body and table tag
    tableHtml += '</tbody></table>';

    // Return the generated HTML table
    return tableHtml;
}
